// ============================================================
return clients.map(c => ({
  json: {
    videoId: videoId,
    apiKey: apiKey,
    clientId: c.clientId,
    context: c.context,
    userAgent: c.context.client.userAgent,
    preferredLanguage: "en",
    botDetected: false
  }
}));

// ============================================================
// Evaluate Player Response & Extract Caption Data
// ============================================================
// Always extracts whatever data is available in the response.
// Sets botDetected = true when:
// - Actual bot block (LOGIN_REQUIRED / "Sign in to confirm")
// - UNPLAYABLE without captions (need to try next client)
// - ERROR / "no longer supported"
// Stops the loop when captions are found.
// ============================================================

const response = $json;
const inputData = $('Clean API Extraction Data').item.json;
const clientId = inputData.clientId;
const videoId = inputData.videoId;
const preferredLanguage = inputData.preferredLanguage;

const status = response.playabilityStatus?.status;
const reason = response.playabilityStatus?.reason || '';

// ============================================================
// Extract video details (available even on UNPLAYABLE)
// ============================================================
const details = response.videoDetails || {};
const micro = response.microformat?.playerMicroformatRenderer || {};

// ============================================================
// Extract caption tracks (may be empty on UNPLAYABLE)
// ============================================================
const captions = response.captions?.playerCaptionsTracklistRenderer;
const captionTracks = captions?.captionTracks || [];

const hasCaptions = captionTracks.length > 0;

// ============================================================
// Bot detection — actual bot blocks OR unplayable without captions
// ============================================================
const botDetected = (
  status === 'LOGIN_REQUIRED' ||
  status === 'ERROR' ||
  (status === 'UNPLAYABLE' && !hasCaptions) ||
  reason.includes('Sign in to confirm') ||
  reason.includes('no longer supported')
);

// ============================================================
// Select best caption track (prefer matching language)
// ============================================================
let selectedTrack = captionTracks.find(
  t => t.languageCode === preferredLanguage
);

// Fallback: first available track
if (!selectedTrack && captionTracks.length > 0) {
  selectedTrack = captionTracks[0];
}

const availableTracks = captionTracks.map(t => ({
  language: t.languageCode,
  name: t.name?.simpleText || t.name?.runs?.[0]?.text || '',
  baseUrl: t.baseUrl,
  isTranslatable: t.isTranslatable || false,
  kind: t.kind || 'standard',
  vssId: t.vssId || ''
}));

// ============================================================
// Output — always includes all available data
// ============================================================
return [{
  json: {
    videoId: details.videoId || videoId,
    videoTitle: details.title || micro.title?.simpleText || 'Unknown',
    videoAuthor: details.author || micro.ownerChannelName || 'Unknown',
    channelId: details.channelId || micro.externalChannelId || '',
    viewCount: details.viewCount || micro.viewCount || '0',
    videoDuration: details.lengthSeconds || micro.lengthSeconds || 0,
    publishDate: micro.publishDate || '',
    description: details.shortDescription || micro.description?.simpleText || '',
    selectedTrack: selectedTrack ? {
      language: selectedTrack.languageCode,
      name: selectedTrack.name?.simpleText || selectedTrack.name?.runs?.[0]?.text || '',
      baseUrl: selectedTrack.baseUrl,
      isTranslatable: selectedTrack.isTranslatable || false,
      kind: selectedTrack.kind || 'standard',
      vssId: selectedTrack.vssId || ''
    } : null,
    availableTracks: availableTracks,
    totalTracks: captionTracks.length,
    trackType: selectedTrack?.kind || 'none',
    clientId: clientId,
    playabilityStatus: status,
    botDetected: botDetected,
    hasCaptions: hasCaptions
  }
}];

// ============================================================
