  text = decodeEntities(text).trim();
  if (!text) continue;

  segments.push({
    text,
    startMs,
    endMs,
    start: formatTime(startMs),
    end: formatTime(endMs),
  });
}

// ============================================================
// Build full transcript text
// ============================================================
const fullText = segments.map((s) => s.text).join(' ');

// ============================================================
// Output
// ============================================================
return [
  {
    json: {
      videoId: meta.videoId,
      title: meta.videoTitle,
      author: meta.videoAuthor,
      language: meta.selectedTrack?.language || null,
      skipped: false,
      fullText,
      segments,
      totalSegments: segments.length,
    },
  },
];

return [{
  json: {
    videoId: $('Loop Over Items').item.json.videoId,
    skipped: true,
    reason: 'no captions available, or every client was blocked by YouTube'
  }
}];

return [{
  json: {
    videoId: $('Clean Base URL and Check for Bot Detection1').item.json.videoId,
    skipped: true,
    reason: 'transcript download failed: ' + ($json.error?.message || 'unknown error')
  }
}];

const videos = $input.all().map(item => item.json);

return [{
  json: {
    totalVideos: videos.length,
    successful: videos.filter(v => !v.skipped).length,
    skipped: videos.filter(v => v.skipped).length,
    videos: videos
  }
}];
